package org.humanjourney.core.mapfeature;
import java.util.*;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import org.humanjourney.core.geography.DiscoveryLedger;
import org.humanjourney.core.water.WaterGeography.Point;
public final class FeaturePackets {
 public static final int PER_PACKET=4,REMOVALS=64,MAX_BYTES=48*1024,MAX_PARTS=512,MAX_FEATURES=2048;
 public enum Mode{FULL,DELTA,CLEAR}public enum Request{INSTANCE}
 public record Header(UUID session,long sequence,long discovery,long catalog){public Header{if(session==null||sequence<=0||discovery<0||catalog<0)throw new IllegalArgumentException("invalid feature revision");}}
 public record Frame(Header header,Mode mode,long base,int part,int parts,List<MapFeature.View> features,List<String> removals,String error){public Frame{features=List.copyOf(features);removals=List.copyOf(removals);if(error==null){Objects.requireNonNull(header);Objects.requireNonNull(mode);if(parts<1||parts>MAX_PARTS||part<0||part>=parts||features.size()>PER_PACKET||removals.size()>REMOVALS||base<0||mode==Mode.DELTA&&(base==0||base>=header.sequence())||mode!=Mode.DELTA&&base!=0||mode==Mode.FULL&&!removals.isEmpty()||mode==Mode.CLEAR&&(parts!=1||!features.isEmpty()||!removals.isEmpty()))throw new IllegalArgumentException("invalid feature transfer bounds");for(String id:removals)if(!DiscoveryLedger.validId(id))throw new IllegalArgumentException("invalid removed feature ID");}}public static Frame bad(String error){return new Frame(null,Mode.FULL,0,0,1,List.of(),List.of(),error);}public boolean valid(){return error==null;}}
 private static int count(RegistryFriendlyByteBuf b,int max){int n=b.readVarInt();if(n<0||n>max)throw new IllegalArgumentException("feature count outside bounds");return n;}
 public static final StreamCodec<RegistryFriendlyByteBuf,Frame> CODEC=new StreamCodec<>(){
 public void encode(RegistryFriendlyByteBuf b,Frame f){if(!f.valid())throw new IllegalArgumentException("rejected feature frame");int start=b.writerIndex();var h=f.header();b.writeUUID(h.session());b.writeVarLong(h.sequence());b.writeVarLong(h.discovery());b.writeVarLong(h.catalog());b.writeVarInt(f.mode().ordinal());b.writeVarLong(f.base());b.writeVarInt(f.part());b.writeVarInt(f.parts());b.writeVarInt(f.features().size());for(var v:f.features()){b.writeUtf(v.id(),64);b.writeUtf(v.label(),128);b.writeVarInt(v.type().ordinal());b.writeUtf(v.dimension(),256);b.writeVarInt(v.priority());b.writeVarInt(v.geometry().kind().ordinal());b.writeVarInt(v.geometry().points().size());for(var p:v.geometry().points()){b.writeDouble(p.x());b.writeDouble(p.z());}}b.writeVarInt(f.removals().size());for(String id:f.removals())b.writeUtf(id,64);if(b.writerIndex()-start>MAX_BYTES)throw new IllegalArgumentException("feature packet exceeds byte limit");}
 public Frame decode(RegistryFriendlyByteBuf b){try{if(b.readableBytes()>MAX_BYTES)throw new IllegalArgumentException("feature packet too large");var h=new Header(b.readUUID(),b.readVarLong(),b.readVarLong(),b.readVarLong());int mode=count(b,Mode.values().length-1);long base=b.readVarLong();int part=b.readVarInt(),parts=b.readVarInt(),n=count(b,PER_PACKET);var features=new ArrayList<MapFeature.View>();for(int i=0;i<n;i++){String id=b.readUtf(64),label=b.readUtf(128);int type=count(b,MapFeature.Type.values().length-1);String dimension=b.readUtf(256);int priority=b.readVarInt(),kind=count(b,FeatureGeometry.Kind.values().length-1),vertices=count(b,512);var points=new ArrayList<Point>();for(int j=0;j<vertices;j++)points.add(new Point(b.readDouble(),b.readDouble()));features.add(new MapFeature.View(id,label,MapFeature.Type.values()[type],dimension,priority,new FeatureGeometry(FeatureGeometry.Kind.values()[kind],points,null)));}var removed=new ArrayList<String>();n=count(b,REMOVALS);for(int i=0;i<n;i++)removed.add(b.readUtf(64));if(b.readableBytes()!=0)throw new IllegalArgumentException("unexpected feature bytes");return new Frame(h,Mode.values()[mode],base,part,parts,features,removed,null);}catch(RuntimeException error){b.skipBytes(b.readableBytes());return Frame.bad("Malformed feature packet: "+error.getClass().getSimpleName());}}
 };
 public static final StreamCodec<RegistryFriendlyByteBuf,Request> REQUEST=StreamCodec.unit(Request.INSTANCE);
 public static List<Frame> frames(Header h,Mode mode,long base,Collection<MapFeature.View> entries,Collection<String> removed){var features=new ArrayList<>(entries);features.sort(Comparator.comparing(MapFeature.View::id));var removals=new ArrayList<>(new TreeSet<>(removed));if(features.size()>MAX_FEATURES||removals.size()>MAX_FEATURES)throw new IllegalArgumentException("feature transfer exceeds catalog limit");int parts=Math.max(1,Math.max((features.size()+PER_PACKET-1)/PER_PACKET,(removals.size()+REMOVALS-1)/REMOVALS));var out=new ArrayList<Frame>();for(int i=0;i<parts;i++){int a=Math.min(i*PER_PACKET,features.size()),k=Math.min(i*REMOVALS,removals.size());out.add(new Frame(h,mode,base,i,parts,features.subList(a,Math.min(a+PER_PACKET,features.size())),removals.subList(k,Math.min(k+REMOVALS,removals.size())),null));}return List.copyOf(out);}
 private FeaturePackets(){}
}
